"""Dependency graphs for pip's offline resolver benchmarks."""

from __future__ import annotations

from pathlib import Path

from . import _support as workloads


class Scenario:
    names = [
        "single",
        "application",
        "pinned",
        "backtracking",
        "selected",
        "stress",
        "wrong-package",
        "transitive",
        "unsatisfiable",
        "nab-basic",
        "nab-constraint",
        "nab-extras",
        "nab-strategy",
        "nab-backtracking",
        "nab-unsatisfiable",
        "nab-backjump",
    ]

    def __init__(self, root: Path, graph: str) -> None:
        self.root = root
        self.wheelhouse = self.root / "wheels"
        self.wheelhouse.mkdir()
        self.constraints = []
        self.unsatisfiable = graph in {"unsatisfiable", "nab-unsatisfiable"}
        if graph in {"single", "application", "pinned"}:
            workloads.make_dependency_graph(self.wheelhouse)
            if graph == "single":
                self.requirements, self.count = (["leaf-0"], 1)
            elif graph == "application":
                self.requirements, self.count = (["application"], 31)
            else:
                self.requirements = [f"middle-{index}==2.2.0" for index in range(10)]
                self.count = 30
        elif graph == "backtracking":
            workloads.make_backtracking_graph(self.wheelhouse)
            self.requirements, self.count = (["conflicting"], 4)
        elif graph == "selected":
            workloads.make_selected_dependency_graph(self.wheelhouse)
            self.requirements, self.count = (["selected-application"], 99)
        elif graph == "stress":
            workloads.make_stress_graph(self.wheelhouse)
            self.requirements = [f"stress-{index}" for index in range(88)]
            self.count = 176
        elif graph in {"wrong-package", "transitive"}:
            builder = (
                workloads.make_wrong_package_graph
                if graph == "wrong-package"
                else workloads.make_transitive_backtracking_graph
            )
            builder(
                self.wheelhouse,
                "boto3-urllib3",
                versions=64 if graph == "wrong-package" else 256,
            )
            self.requirements, self.count = (["boto3-urllib3-root"], 4)
        elif graph == "unsatisfiable":
            for index in range(24):
                for version in ("1.0.0", "2.0.0"):
                    workloads.make_wheel(
                        self.wheelhouse, f"unsat-shared-{index}", version
                    )
                workloads.make_wheel(
                    self.wheelhouse,
                    f"unsat-branch-{index}",
                    "1.0.0",
                    requires=[f"unsat-shared-{index}==1.0.0"],
                )
            self.requirements = [
                r
                for i in range(24)
                for r in (f"unsat-branch-{i}", f"unsat-shared-{i}==2.0.0")
            ]
        elif graph in {"nab-backtracking", "nab-unsatisfiable"}:
            workloads.make_nab_pip_backtracking_family(
                self.wheelhouse, "nab-smoke-pip", 24, unsatisfiable=self.unsatisfiable
            )
            self.requirements, self.count = (["nab-smoke-pip-a"], 3)
        elif graph == "nab-backjump":
            workloads.make_nab_deep_backjump_family(
                self.wheelhouse, "nab-smoke-backjump", 6
            )
            self.requirements = [
                "nab-smoke-backjump-pivot",
                "nab-smoke-backjump-link-1",
            ]
            self.count = 14
        else:
            workloads.make_nab_smoke_fixture(self.wheelhouse)
            self.requirements, self.count = {
                "nab-basic": (["nab-smoke-basic"], 2),
                "nab-constraint": (["nab-smoke-constrained"], 1),
                "nab-extras": (["nab-smoke-extra-app[speed]"], 4),
                "nab-strategy": (
                    ["nab-smoke-strategy-app==1.0.0", "nab-smoke-strategy-direct>=1"],
                    3,
                ),
            }[graph]
            if graph == "nab-constraint":
                self.constraints = ["nab-smoke-constrained<3"]

"""Simple API parsing and candidate ranking via upstream pip's finder."""

from __future__ import annotations

import pytest
from pytest_benchmark.fixture import BenchmarkFixture

from pip._vendor.packaging.specifiers import SpecifierSet
from pip._vendor.packaging.utils import canonicalize_name

from pip._internal.index.collector import IndexContent, parse_links
from pip._internal.index.package_finder import CandidateEvaluator, LinkEvaluator
from pip._internal.models.candidate import InstallationCandidate
from pip._internal.models.link import Link
from pip._internal.models.target_python import TargetPython
from pip._internal.models.wheel import Wheel

from ._support import simple_index_html, simple_index_json, wheel_filenames

URL = "https://example.invalid/simple/package/"
FILENAMES = wheel_filenames()


@pytest.mark.parametrize("format", ["html", "json"])
@pytest.mark.parametrize("pages", [1, 32])
def test_parse_index(benchmark: BenchmarkFixture, format: str, pages: int) -> None:
    count = 400 if pages == 1 else 200
    body = simple_index_html(count) if format == "html" else simple_index_json(count)
    content_type = (
        "text/html" if format == "html" else "application/vnd.pypi.simple.v1+json"
    )
    contents = [
        IndexContent(
            body.encode(),
            content_type,
            "utf-8",
            f"{URL}{index}/",
            cache_link_parsing=False,
        )
        for index in range(pages)
    ]
    result = benchmark(lambda: [list(parse_links(page)) for page in contents])
    assert sum(map(len, result)) == count * pages * (2 if format == "html" else 1)
    assert all(
        link.metadata_file_data is not None for links in result for link in links
    )


def test_parse_wheel_filenames(benchmark: BenchmarkFixture) -> None:
    assert len(benchmark(lambda: [Wheel(name) for name in FILENAMES])) == 400


def test_rank_wheel_tags(benchmark: BenchmarkFixture) -> None:
    wheels = [Wheel(name) for name in FILENAMES]
    tags = TargetPython().get_sorted_tags()
    result = benchmark(
        lambda: [
            wheel.support_index_min(tags) for wheel in wheels if wheel.supported(tags)
        ]
    )
    assert len(result) >= 200


@pytest.mark.parametrize("prefer_binary", [False, True])
def test_select_candidate(benchmark: BenchmarkFixture, prefer_binary: bool) -> None:
    candidates = [
        InstallationCandidate(
            "package",
            f"1.{index}.0",
            Link(f"https://example.invalid/package-1.{index}.0-py3-none-any.whl"),
        )
        for index in range(400)
    ]
    candidates.append(
        InstallationCandidate(
            "package", "1.400.0", Link("https://example.invalid/package-1.400.0.tar.gz")
        )
    )
    evaluator = CandidateEvaluator.create(
        "package", specifier=SpecifierSet(">=1.10,<2"), prefer_binary=prefer_binary
    )
    result = benchmark(evaluator.compute_best_candidate, candidates)
    assert result.best_candidate is not None
    assert str(result.best_candidate.version) == (
        "1.399.0" if prefer_binary else "1.400.0"
    )


@pytest.mark.parametrize(
    "platform",
    [
        "manylinux_2_17_x86_64",
        "win_amd64",
        "macosx_11_0_arm64",
        "musllinux_1_2_aarch64",
    ],
)
def test_filter_target_matrix(benchmark: BenchmarkFixture, platform: str) -> None:
    links = [
        Link(f"https://example.invalid/{name}", requires_python=">=3.9")
        for name in FILENAMES
    ]
    evaluators = [
        LinkEvaluator(
            project_name="package",
            canonical_name=canonicalize_name("package"),
            formats=frozenset(["binary", "source"]),
            target_python=TargetPython(
                platforms=[platform], py_version_info=(3, minor)
            ),
            allow_yanked=False,
            ignore_requires_python=False,
        )
        for minor in range(9, 14)
    ]
    result = benchmark(
        lambda: [
            evaluator.evaluate_link(link) for evaluator in evaluators for link in links
        ]
    )
    assert len(result) == 2000
    assert sum(kind.name == "candidate" for kind, _ in result) >= 1000

